CUR_CSS='\n.curwrap{position:relative;display:inline-flex}\n.ibtn.cur svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}\n.ibtn.cur .cc{font:600 11.5px/1 var(--f-lat);letter-spacing:.08em;direction:ltr}\n.curmenu{position:absolute;top:calc(100% + 8px);inset-inline-end:0;z-index:60;min-width:244px;padding:6px;border-radius:16px;border:1px solid var(--line-2);background:var(--paper);box-shadow:0 22px 50px -22px rgba(15,23,48,.5);direction:ltr}\n.curmenu[hidden]{display:none}\n.curmenu .ch{display:block;padding:8px 10px 6px;font:500 11px/1 var(--f-lat);letter-spacing:.22em;text-transform:uppercase;color:var(--faint)}\n.curmenu button{display:flex;align-items:center;gap:11px;width:100%;padding:9px 10px;border:0;border-radius:11px;background:transparent;color:var(--ink);cursor:pointer;font:500 15px/1.2 var(--f-lat);text-align:start}\n.curmenu button:hover,.curmenu button:focus-visible{background:var(--line)}\n.curmenu button[aria-checked="true"]{background:var(--line);color:var(--head)}\n.curmenu button[aria-checked="true"]::after{content:"";margin-inline-start:auto;width:7px;height:7px;border-radius:50%;background:var(--cyan-ink)}\n.curmenu .fl{width:28px;height:19px;border-radius:4px;flex:none;box-shadow:0 0 0 1px rgba(15,23,48,.18)}\n.curmenu .nm{white-space:nowrap;margin-inline-start:2px;font-weight:400;font-size:12.5px;color:var(--muted)}\n.curnote{display:block;padding:8px 10px 6px;font:400 11.5px/1.5 var(--f-ar);color:var(--faint);direction:inherit;border-top:1px solid var(--line);margin-top:4px}\n@media (max-width:520px){.ibtn.cur{width:40px;padding-inline:0}.ibtn.cur .cc{display:none}.tools{gap:4px}}\n@media (max-width:380px){.top .lname{display:none}.bar{gap:8px}}\n@media (max-width:320px){.tools{gap:2px}.top .ibtn{padding-inline:9px;min-width:36px}.ibtn.cur{width:36px}.bar{padding-inline:10px 6px}}\n@media (max-width:320px){.k{letter-spacing:.16em;overflow-wrap:anywhere}}\n'
CUR_BTN='<div class="curwrap"><button class="ibtn cur" type="button" id="curBtn" aria-haspopup="menu" aria-expanded="false" aria-label="العملة"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9.5"/><path d="M12 5.6v12.8"/><path d="M15.4 9.3c0-1.3-1.5-2.1-3.4-2.1s-3.4.9-3.4 2.2c0 3.2 6.8 1.5 6.8 4.7 0 1.3-1.5 2.3-3.4 2.3s-3.4-.9-3.4-2.2"/></svg><span class="cc" id="curCode">JD</span></button><div class="curmenu" id="curMenu" role="menu" hidden></div></div>'
